class Cart:
    def __init__(self, items):
        self.items = items

    def total(self):
        subtotal = self._subtotal()
        if subtotal > 100:
            subtotal *= 0.95
        return round(subtotal, 2)

    def _subtotal(self):
        return sum(item.price * item.qty for item in self.items)
